#!/usr/bin/env node
/**
 * Build both halves of the plugin.
 *
 * Host half: ESM for Node, with every `@deepseek-ai/*` package and zod left
 * external so the running installation supplies its own instances.
 *
 * Browser half: the client module system is a lazy CommonJS table
 * (`window.__ModuleLoader__.load({ id, factory })`) whose `require` resolves
 * the shell's platform modules, so the bundle must be CommonJS, must keep the
 * baseline modules as bare `require(...)` calls, and must inline everything
 * else. This script reproduces that contract (the repo's own preset is not a
 * published package) and then asserts it on the produced artifact.
 *
 * Usage: node scripts/build.mjs [--watch]
 */
import { build, context } from 'esbuild'
import { readFile, writeFile, mkdir, rm, rename } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const OUT = join(ROOT, 'lib')
const PACKAGE_NAME = 'dsh-highlights'

/**
 * Modules the shell's module table provides to every plugin bundle.
 * Mirrors PLATFORM_MODULES in packages/client/web/src/platform.ts.
 */
const PLATFORM_MODULES = [
  'react',
  'react/jsx-runtime',
  'react-dom',
  'react-dom/client',
  '@deepseek-ai/cordis',
  'zod',
  '@tanstack/react-virtual',
  '@deepseek-ai/dsh-client-store',
  '@deepseek-ai/dsh-client-ui-slots',
  '@deepseek-ai/dsh-client-ui-primitives',
  '@deepseek-ai/dsh-client-ui-dockkit',
]

/** Host-half externals: resolved by Node from the profile/installation. */
const HOST_EXTERNALS = ['@deepseek-ai/*', 'zod']

/**
 * Wrap a CommonJS bundle in the client module system's factory registration.
 * @param body - Compiled CommonJS source.
 * @returns the wrapped plugin script.
 */
function wrapClientBundle(body) {
  return [
    '/* dsh-highlights client bundle — generated by scripts/build.mjs; do not edit. */',
    'window.__ModuleLoader__.load({',
    `  id: ${JSON.stringify(PACKAGE_NAME)},`,
    '  factory: (require) => {',
    '    var module = { exports: {} };',
    '    var exports = module.exports;',
    body,
    '    return module.exports;',
    '  },',
    '});',
    '',
  ].join('\n')
}

/**
 * Assert the produced browser bundle honours the module-table contract.
 * @param source - Wrapped bundle source.
 */
function assertClientContract(source) {
  const requires = [...source.matchAll(/require\(\s*["']([^"']+)["']\s*\)/gu)].map(match => match[1])
  const unexpected = [...new Set(requires.filter(id => !PLATFORM_MODULES.includes(id)))]
  if (unexpected.length > 0) {
    throw new Error(`client bundle requires modules outside the platform table: ${unexpected.join(', ')}`)
  }
  for (const required of ['react', 'react/jsx-runtime']) {
    if (!requires.includes(required)) {
      throw new Error(`client bundle never requires "${required}"; the JSX transform is not externalised correctly`)
    }
  }
  if (!source.includes(`window.__ModuleLoader__.load`)) throw new Error('client bundle is not module-loader wrapped')
  if (source.includes('node_modules/react/')) throw new Error('client bundle inlined React; it must stay external')
}

/** Host-half build options. */
/** Client-bundle ceiling in KiB; the G1 budget gate fails the build above this. */
const CLIENT_BUNDLE_BUDGET_KIB = 320

const hostOptions = {
  entryPoints: [join(ROOT, 'src/host/index.ts')],
  outfile: join(OUT, 'index.js'),
  bundle: true,
  format: 'esm',
  platform: 'node',
  target: 'node24',
  sourcemap: true,
  external: HOST_EXTERNALS,
  logLevel: 'info',
}

/** Browser-half build options (pre-wrap, CommonJS). */
const clientOptions = {
  entryPoints: [join(ROOT, 'src/client/index.ts')],
  outfile: join(OUT, 'client.raw.cjs'),
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  target: 'es2022',
  jsx: 'automatic',
  // Minified with an external map: the inline map was ~90% of the artifact
  // (1171 KiB inline vs 165 KiB without), and the plugin's source ships in the repo.
  minify: true,
  sourcemap: 'external',
  external: PLATFORM_MODULES,
  define: { 'process.env.NODE_ENV': '"production"' },
  logLevel: 'info',
}

/**
 * Run the whole build.
 * @returns completion.
 */
async function buildAll() {
  await mkdir(OUT, { recursive: true })
  await build(hostOptions)
  await build(clientOptions)
  const raw = await readFile(join(OUT, 'client.raw.cjs'), 'utf8')
  // esbuild points the map at the intermediate file name; the shipped artifact is client.js.
  const body = raw.replace(/^\/\/# sourceMappingURL=.*$/mu, '')
  const wrapped = `${wrapClientBundle(body)}//# sourceMappingURL=client.js.map\n`
  assertClientContract(wrapped)
  await rename(join(OUT, 'client.raw.cjs.map'), join(OUT, 'client.js.map'))
  await writeFile(join(OUT, 'client.js'), wrapped, 'utf8')
  await rm(join(OUT, 'client.raw.cjs'), { force: true })
  const bytes = Buffer.byteLength(wrapped, 'utf8')
  const kib = bytes / 1024
  // Budget gate (G1). The UI/UX programme may grow the client bundle, but not
  // silently: raising this ceiling is a deliberate, reviewable edit.
  if (kib > CLIENT_BUNDLE_BUDGET_KIB) {
    throw new Error(`client bundle ${kib.toFixed(1)} KiB exceeds the ${CLIENT_BUNDLE_BUDGET_KIB} KiB budget`)
  }
  console.log(`client bundle: ${kib.toFixed(1)} KiB (budget ${CLIENT_BUNDLE_BUDGET_KIB} KiB), contract OK`)
}

const watch = process.argv.includes('--watch')

if (watch) {
  await mkdir(OUT, { recursive: true })
  const hostCtx = await context({ ...hostOptions, plugins: [] })
  const clientCtx = await context(clientOptions)
  await hostCtx.watch()
  await clientCtx.watch()
  console.log('watching… (client wrapper is produced by a full `pnpm build` run)')
} else {
  await buildAll()
}
